tool.command:
mkdir -p libreqda_data ;
#if $database
    cp '$database' '$database_out' ;
#end if
export HOME=\$PWD/libreqda_data ;
exec libreqda --no-browser server libreqda_server_config.py

citations.citation:
@misc{libreqda,
            author = {Dion, Jérémie and Legault, Ève and Claveau, François and Touré, Moussa and Boissonneault, Philippe},
            title = {LibreQDA: qualitative data analysis software},
            year = {2025},
            publisher = {GitLab},
            howpublished = {\url{https://gitlab.com/bin-cirst/libreqda/libre-qda}},
            note = {Université de Sherbrooke, Plateforme en humanités numériques}
        }
